// ---- src/logic/phone.ts ----
// Phone number helpers. South Africa (+27) is the default country.
// Twilio reports a withheld caller ID as "anonymous" or as +266696687 (ANONYMOUS on a keypad).
const WITHHELD_CALLER_IDS = [
  '',
  'anonymous',
  'restricted',
  'unknown',
  'private',
  'unavailable',
  'blocked',
  '+266696687',
  '266696687',
];

const E164_PATTERN = /^\+[1-9]\d{6,14}$/;

// Turns whatever the phone system sends into E.164, for example "+27000000012".
// Handles "082 ...", "27 82 ...", "0027 ...", "+27 (0)82 ..." and "sip:+27...@host".
const normalisePhone = (raw, defaultCountryCode = '27') => {
  const text = String(raw ?? '').trim().toLowerCase();
  if (WITHHELD_CALLER_IDS.includes(text)) {
    return { ok: false, issue: 'withheld' };
  }
  const withoutUri = text.replace(/^(sips?|tel):/, '').replace(/@.*$/, '');
  const withoutTrunkZero = withoutUri.replace(/\(0\)/g, '');
  const hasPlus = withoutTrunkZero.startsWith('+');
  const digits = withoutTrunkZero.replace(/\D/g, '');
  if (digits !== '' && WITHHELD_CALLER_IDS.includes(digits)) {
    return { ok: false, issue: 'withheld' };
  }
  const cc = defaultCountryCode;
  let e164 = '';
  if (hasPlus) {
    e164 = `+${digits}`;
  }
  else if (/^00[1-9]/.test(digits)) {
    e164 = `+${digits.slice(2)}`;
  }
  else if (digits.startsWith(cc) && digits.length === cc.length + 9) {
    e164 = `+${digits}`;
  }
  else if (digits.startsWith('0') && digits.length === 10) {
    e164 = `+${cc}${digits.slice(1)}`;
  }
  // "+27 0xx xxx xxxx" typed with the local trunk zero still in it.
  if (e164.startsWith(`+${cc}0`) && e164.length === cc.length + 11) {
    e164 = `+${cc}${e164.slice(cc.length + 2)}`;
  }
  return E164_PATTERN.test(e164) ? { ok: true, e164 } : { ok: false, issue: 'invalid' };
};

// Allowed prefixes come from Config as a comma separated list, for example "+27".
const parsePrefixList = (value) => String(value ?? '')
  .split(',')
  .map((part) => part.trim())
  .filter((part) => /^\+\d{1,4}$/.test(part));

const isAllowedCountry = (e164, allowedPrefixes) => allowedPrefixes.length === 0 || allowedPrefixes.some((prefix) => e164.startsWith(prefix));

// "+27000000012" becomes "+27 00 000 0012" for alerts a manager reads.
const formatPhoneForPeople = (e164) => {
  const match = /^\+27(\d{2})(\d{3})(\d{4})$/.exec(e164);
  return match ? `+27 ${match[1]} ${match[2]} ${match[3]}` : e164;
};

// ---- src/logic/clock.ts ----
// Time helpers. Every decision takes "now" as an input so tests and the demo can replay a whole day.
const toUtcIso = (value) => value.toUTC().toISO() ?? '';

// Uses the x-hs-test-clock header only when Config has test_clock_enabled set to true.
// It ships switched off. The e2e harness switches it on to replay a synthetic day.
const resolveNow = (realNowIso, testClockEnabled, testClockHeader) => {
  if (testClockEnabled === true && typeof testClockHeader === 'string' && testClockHeader.trim() !== '') {
    const fake = DateTime.fromISO(testClockHeader.trim(), { setZone: true });
    if (fake.isValid) {
      return toUtcIso(fake);
    }
  }
  return toUtcIso(DateTime.fromISO(realNowIso, { setZone: true }));
};

// Accepts an ISO string or a Date, which is what Postgres drivers hand back for timestamptz.
const toIso = (value) => {
  if (value === null || value === undefined || value === '') {
    return null;
  }
  const parsed = value instanceof Date
    ? DateTime.fromJSDate(value)
    : DateTime.fromISO(String(value), { setZone: true });
  return parsed.isValid ? toUtcIso(parsed) : null;
};

const minutesBetween = (fromIso, toIsoValue) => DateTime.fromISO(toIsoValue).diff(DateTime.fromISO(fromIso), 'minutes').minutes;

const minuteOfDay = (hhmm) => {
  const match = /^(\d{1,2}):(\d{2})$/.exec(hhmm.trim());
  if (!match) {
    throw new Error(`Expected a time like 21:00, got "${hhmm}"`);
  }
  return Number(match[1]) * 60 + Number(match[2]);
};

// Quiet hours can wrap midnight, for example 21:00 to 08:00. The end minute is not quiet.
const isQuietHours = (nowIso, timezone, quietStart, quietEnd) => {
  const local = DateTime.fromISO(nowIso).setZone(timezone);
  const minute = local.hour * 60 + local.minute;
  const start = minuteOfDay(quietStart);
  const end = minuteOfDay(quietEnd);
  if (start === end) {
    return false;
  }
  return start < end ? minute >= start && minute < end : minute >= start || minute < end;
};

// The next time the clock reads quietEnd in the business timezone, strictly after now.
const nextQuietEnd = (nowIso, timezone, quietEnd) => {
  const local = DateTime.fromISO(nowIso).setZone(timezone);
  const minute = minuteOfDay(quietEnd);
  let target = local.set({ hour: Math.floor(minute / 60), minute: minute % 60, second: 0, millisecond: 0 });
  if (target <= local) {
    target = target.plus({ days: 1 });
  }
  return toUtcIso(target);
};

// Twilio sends Timestamp as RFC 2822, for example "Fri, 16 Oct 2026 10:05:00 +0000".
const parseTwilioTimestamp = (value) => {
  if (typeof value !== 'string' || value.trim() === '') {
    return null;
  }
  const parsed = DateTime.fromRFC2822(value.trim());
  return parsed.isValid ? toUtcIso(parsed) : null;
};

// The report covers one calendar day in the business timezone. By default that is yesterday.
const reportWindow = (nowIso, timezone, requestedDate) => {
  const asked = typeof requestedDate === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(requestedDate)
    ? DateTime.fromISO(requestedDate, { zone: timezone })
    : null;
  const day = asked && asked.isValid
    ? asked.startOf('day')
    : DateTime.fromISO(nowIso).setZone(timezone).startOf('day').minus({ days: 1 });
  return {
    date: day.toISODate() ?? '',
    label: day.toFormat('cccc d LLLL yyyy'),
    startIso: toUtcIso(day),
    endIso: toUtcIso(day.plus({ days: 1 })),
  };
};

const isWithin = (iso, startIso, endIso) => {
  if (!iso) {
    return false;
  }
  const at = DateTime.fromISO(iso).toMillis();
  return at >= DateTime.fromISO(startIso).toMillis() && at < DateTime.fromISO(endIso).toMillis();
};

const localTimeLabel = (iso, timezone) => DateTime.fromISO(iso).setZone(timezone).toFormat('HH:mm');

const hoursBefore = (iso, hours) => toUtcIso(DateTime.fromISO(iso).minus({ hours }));

const daysBefore = (iso, days) => toUtcIso(DateTime.fromISO(iso).minus({ days }));

// ---- src/logic/callStatus.ts ----
// Reads a Twilio voice status callback and decides whether it is a missed call worth texting.
const SID_PATTERN = /^[A-Za-z0-9_-]{1,64}$/;

const readSid = (value) => {
  const text = String(value ?? '').trim();
  return SID_PATTERN.test(text) ? text : null;
};

const parseStatusList = (value) => String(value ?? '')
  .split(',')
  .map((status) => status.trim().toLowerCase())
  .filter((status) => status !== '');

// Idempotency key: ParentCallSid when present, else CallSid.
// A <Dial> that rings two handsets sends one callback per handset for the same customer call.
// Keying on the parent call means that customer still gets exactly one text.
const parseStatusCallback = (body, options) => {
  const callSid = readSid(body.CallSid);
  const parentCallSid = readSid(body.ParentCallSid);
  const callStatus = String(body.CallStatus ?? body.DialCallStatus ?? '').trim().toLowerCase();
  const calledAtIso = parseTwilioTimestamp(body.Timestamp) ?? options.nowIso;
  const base = {
    isMissed: false,
    ignoreReason: null,
    callKey: parentCallSid ?? callSid ?? '',
    callSid: callSid ?? '',
    parentCallSid,
    callStatus,
    callerE164: null,
    callerIssue: null,
    calledAtIso,
  };
  if (!callSid) {
    return { ...base, ignoreReason: 'no CallSid in the callback' };
  }
  if (!options.missedStatuses.includes(callStatus)) {
    return { ...base, ignoreReason: `status ${callStatus || 'empty'} is not a missed call` };
  }
  const phone = normalisePhone(body.From ?? body.Caller);
  if (!phone.ok) {
    return { ...base, isMissed: true, callerIssue: phone.issue };
  }
  if (!isAllowedCountry(phone.e164, options.allowedPrefixes)) {
    return { ...base, isMissed: true, callerE164: phone.e164, callerIssue: 'foreign' };
  }
  return { ...base, isMissed: true, callerE164: phone.e164 };
};

// ---- src/logic/config.ts ----
// Reads the values the Config node adds to every item. Fails loudly when a value is missing.
const configString = (item, key) => {
  const value = item[key];
  if (typeof value !== 'string' || value.trim() === '') {
    throw new Error(`Config is missing "${key}". Open the Config node and fill it in.`);
  }
  return value.trim();
};

const configNumber = (item, key) => {
  const value = Number(item[key]);
  if (item[key] === '' || item[key] === null || item[key] === undefined || !Number.isFinite(value)) {
    throw new Error(`Config "${key}" must be a number.`);
  }
  return value;
};

const configFlag = (item, key) => item[key] === true || item[key] === 'true';

const readRecord = (value) => value !== null && typeof value === 'object' && !Array.isArray(value) ? value : {};

// ---- src/nodes/readCallStatus.ts ----
// Code node "Read call status" in workflow 1. Input: the Config item, which carries the webhook request.
const readCallStatus = (item, realNowIso) => {
  const headers = readRecord(item.headers);
  const nowIso = resolveNow(realNowIso, configFlag(item, 'test_clock_enabled'), headers['x-hs-test-clock']);
  const call = parseStatusCallback(readRecord(item.body), {
    missedStatuses: parseStatusList(configString(item, 'missed_statuses')),
    allowedPrefixes: parsePrefixList(configString(item, 'allowed_country_prefixes')),
    nowIso,
  });
  return {
    is_missed: call.isMissed,
    ignore_reason: call.ignoreReason,
    call_key: call.callKey,
    call_sid: call.callSid,
    parent_call_sid: call.parentCallSid,
    call_status: call.callStatus,
    caller_e164: call.callerE164,
    caller_issue: call.callerIssue,
    called_at: call.calledAtIso,
    now_iso: nowIso,
  };
};

// ---- n8n entry point ----
return [{ json: readCallStatus($input.first().json, $now.toISO()) }];

