  alert_text: `${business}: ${formatPhoneForPeople(fromE164)} asked for the booking link, but the SMS failed. `
    + `${error}. Please send it by hand.`,
});

// ---- src/logic/config.ts ----
// Reads the values the Config node adds to every item. Fails loudly when a value is missing.
const configString = (item, key) => {
  const value = item[key];
  if (typeof value !== 'string' || value.trim() === '') {
    throw new Error(`Config is missing "${key}". Open the Config node and fill it in.`);
  }
  return value.trim();
};

const configNumber = (item, key) => {
  const value = Number(item[key]);
  if (item[key] === '' || item[key] === null || item[key] === undefined || !Number.isFinite(value)) {
    throw new Error(`Config "${key}" must be a number.`);
  }
  return value;
};

const configFlag = (item, key) => item[key] === true || item[key] === 'true';

const readRecord = (value) => value !== null && typeof value === 'object' && !Array.isArray(value) ? value : {};

// ---- src/nodes/failureAlert.ts ----
// Code node "Failure alert" in workflow 1. One alert per text that Twilio refused (the dead letter path).
const failureAlert = (rows, cfg) => rows
  .filter((row) => row.outcome === 'failed' && typeof row.caller_e164 === 'string')
  .map((row) => ({
  call_key: String(row.call_key),
  ...failedSmsAlert(configString(cfg, 'business_name'), String(row.caller_e164), toIso(row.called_at) ?? '', configString(cfg, 'timezone'), String(row.last_error ?? 'unknown error')),
}));

// ---- n8n entry point ----
return failureAlert($input.all().map((item) => item.json), $('Config').first().json).map((json) => ({ json }));
